namespace Kaitai\Struct\Tests;

class ExprCalcIntPromotionTest extends TestCase {
    public function testExprCalcIntPromotion() {
        $r = ExprCalcIntPromotion::fromFile(self::SRC_DIR_PATH . '/expr_calc_int_promotion.bin');
        $this->assertSame(3, $r->u4Val());
        $this->assertSame(4294967301, $r->u8Val());
        $this->assertSame(-4294967296, $r->s8Val());
        $this->assertSame("ABC", $r->items()[0]);
        $this->assertSame("DEFG", $r->items()[1]);
        $this->assertSame(24, $r->ioSizeMinusU4());
        $this->assertSame(4294967328, $r->u8PlusIoSize());
        $this->assertSame(4294967323, $r->ioSizeMinusS8());
        $this->assertSame(16, $r->ioSizeAndU4Lit());
    }
}
